const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='pati-champions-v1', LIMIT=8*3600;
const initial=()=>({version:1,skillPoints:8,campusUpgrades:{},money:3500,gems:8,xp:0,levels:[1,1,1,1,1,1],hurdleLevels:[1,1,1,1],swimLevels:[1,1,1,1],longJumpLevels:[1,1,1,1],bestJump:0,weightLevels:[1,1,1,1],bestWeight:0,archeryLevels:[1,1,1,1],bestArchery:0,tournament:null,tournamentCups:0,weightRisk:'safe',branch:'sprint',races:0,wins:0,medals:0,best:null,selected:0,name:'Pati Takımı',auto:true,sound:true,musicVolume:0.6,soundVolume:0.4,vibration:true,claims:[],camp:1,equipment:0,equipmentStars:[0,0,0,0],equipmentLegacy:0,chests:0,cupChests:0,championChests:0,equipmentParts:0,trainingCards:{},cosmetics:[],selectedCosmetic:-1,pendingChest:null,boostTokens:0,boostUntil:0,boostReady:0,last:Date.now(),daily:0,dailyStep:0,spinDate:"",spinTickets:0});
let state=initial(), storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&raw.version===1){state={...state,...raw};if(!Array.isArray(state.levels))state.levels=[];state.levels=[...state.levels.slice(0,6),...Array(6).fill(1)].slice(0,6).map(n=>Math.max(1,Math.min(100,Math.floor(Number(n)||1))));state.money=Math.max(0,Number(state.money)||0);state.gems=Math.max(0,Number(state.gems)||0);state.selected=Math.max(0,Math.min(5,Number(state.selected)||0));state.claims=Array.isArray(state.claims)?state.claims:[];const oldEquipment=Math.max(0,Math.floor(Number(state.equipment)||0));state.equipmentStars=Array.isArray(raw.equipmentStars)?[...raw.equipmentStars.slice(0,4),0,0,0,0].slice(0,4).map(v=>Math.max(0,Math.min(3,Math.floor(Number(v)||0)))):[Math.min(3,oldEquipment),0,0,0];state.equipmentLegacy=Array.isArray(raw.equipmentStars)?Math.max(0,Math.floor(Number(raw.equipmentLegacy)||0)):Math.max(0,oldEquipment-3);state.chests=Math.max(0,Math.floor(Number(state.chests)||0));state.boostTokens=Math.max(0,Math.floor(Number(state.boostTokens)||0));}}catch(e){storageOK=false;}
state.skillPoints=Math.max(0,Math.floor(Number(state.skillPoints)||0));
state.branch=['sprint','hurdles','swim','longjump','weights','archery'].includes(state.branch)?state.branch:'sprint';
state.longJumpLevels=Array.isArray(state.longJumpLevels)?[...state.longJumpLevels.slice(0,4),1,1,1,1].slice(0,4).map(n=>Math.max(1,Math.min(100,Math.floor(Number(n)||1)))):[1,1,1,1];
state.bestJump=Math.max(0,Number(state.bestJump)||0);
state.weightLevels=Array.isArray(state.weightLevels)?[...state.weightLevels.slice(0,4),1,1,1,1].slice(0,4).map(n=>Math.max(1,Math.min(100,Math.floor(Number(n)||1)))):[1,1,1,1];
state.bestWeight=Math.max(0,Number(state.bestWeight)||0);
state.archeryLevels=Array.isArray(state.archeryLevels)?[...state.archeryLevels.slice(0,4),1,1,1,1].slice(0,4).map(n=>Math.max(1,Math.min(100,Math.floor(Number(n)||1)))):[1,1,1,1];
state.bestArchery=Math.max(0,Number(state.bestArchery)||0);
state.tournament=state.tournament&&['sprint','hurdles','swim','longjump','weights','archery'].includes(state.tournament.branch)?{branch:state.tournament.branch,attempts:Math.max(0,Math.min(3,Math.floor(Number(state.tournament.attempts)||0))),podiums:Math.max(0,Math.min(3,Math.floor(Number(state.tournament.podiums)||0)))}:null;
state.tournamentCups=Math.max(0,Math.floor(Number(state.tournamentCups)||0));
state.cupChests=Math.max(0,Math.floor(Number(state.cupChests)||0));state.championChests=Math.max(0,Math.floor(Number(state.championChests)||0));state.equipmentParts=Math.max(0,Math.floor(Number(state.equipmentParts)||0));state.trainingCards=state.trainingCards&&typeof state.trainingCards==='object'&&!Array.isArray(state.trainingCards)?state.trainingCards:{};state.cosmetics=Array.isArray(state.cosmetics)?[...new Set(state.cosmetics.filter(i=>Number.isInteger(i)&&i>=0&&i<4))]:[];state.selectedCosmetic=state.cosmetics.includes(state.selectedCosmetic)?state.selectedCosmetic:-1;if(!state.pendingChest||!['normal','cup','champion'].includes(state.pendingChest.type)||!Array.isArray(state.pendingChest.offers)||state.pendingChest.offers.length!==3)state.pendingChest=null;
state.weightRisk=state.weightRisk==='record'?'record':'safe';
state.swimLevels=Array.isArray(state.swimLevels)?[...state.swimLevels.slice(0,4),1,1,1,1].slice(0,4).map(n=>Math.max(1,Math.min(100,Math.floor(Number(n)||1)))):[1,1,1,1];
state.hurdleLevels=Array.isArray(state.hurdleLevels)?[...state.hurdleLevels.slice(0,4),1,1,1,1].slice(0,4).map(n=>Math.max(1,Math.min(100,Math.floor(Number(n)||1)))):[1,1,1,1];
if(!state.campusUpgrades||typeof state.campusUpgrades!=='object'||Array.isArray(state.campusUpgrades))state.campusUpgrades={};
function campusRank(id,i){return Math.max(0,Math.min(5,Math.floor(Number(state.campusUpgrades?.[id]?.[i])||0)));}
const art={avatar:[69,58,73,75],trophy:[67,163,77,74],shoe:[64,1009,75,72],speed:[515,1009,76,71],stamina:[66,1273,80,64],finish:[514,1267,77,69],clipboard:[35,1524,96,97],bag:[174,1528,79,93],cards:[301,1530,75,91],camp:[553,1530,85,92],medal:[685,1529,74,93],shop:[805,1527,101,93],cheetah:[705,524,38,38],raccoon:[623,576,36,35],bear:[493,609,36,35],rabbit:[374,650,36,35],turtle:[404,710,33,31],fox:[521,758,36,35]};
