function paintArt(el,key){el.textContent='';if(paintWeightArt(el,key)||paintArcheryArt(el,key))return;const jumpIcons={'jump-start':[46,999,107,88],'jump-steps':[500,998,110,92],'jump-power':[43,1252,111,92],'jump-land':[498,1252,111,92]};if(jumpIcons[key]){const r=jumpIcons[key];el.style.backgroundImage="url('assets/jump-icons-source.png')";el.style.backgroundSize=`${941/r[2]*100}% ${1672/r[3]*100}%`;el.style.backgroundPosition=`${r[0]/(941-r[2])*100}% ${r[1]/(1672-r[3])*100}%`;return;}const swimIcons={'swim-dive':'🏊','swim-paw':'🐾','swim-breath':'🤿','swim-wave':'🌊'};if(swimIcons[key]){el.style.backgroundImage='none';el.textContent=swimIcons[key];return;}const g=iconGrid[key];if(g){el.style.backgroundImage="url('assets/ui-icons.png')";el.style.backgroundSize='600% 300%';el.style.backgroundPosition=`${g[0]*20}% ${g[1]*50}%`;return;}const r=art[key]||art.avatar;el.style.backgroundImage="url('assets/reference.png')";el.style.backgroundSize=`${941/r[2]*100}% ${1672/r[3]*100}%`;el.style.backgroundPosition=`${r[0]/(941-r[2])*100}% ${r[1]/(1672-r[3])*100}%`;}
function arts(root=document){root.querySelectorAll('[data-art]').forEach(el=>paintArt(el,el.dataset.art));}
arts();
