const weightUpgrades=[{title:'Temel Güç',icon:'weight-strength',base:1000,desc:'Her seviye hedef kaldırış ağırlığını %2,5 artırır.'},{title:'Kavrama',icon:'weight-grip',base:1100,desc:'Her seviye başarılı kaldırış şansını 0,8 yüzde puan artırır.'},{title:'Denge',icon:'weight-balance',base:950,desc:'Her seviye başarılı kaldırış şansını 0,9 yüzde puan artırır.'},{title:'Son Hamle',icon:'weight-finish',base:1200,desc:'Her seviye ağırlığı %1 ve başarı şansını 0,3 yüzde puan artırır. Başarı şansı en fazla %98 olur.'}];
const archeryUpgrades=[{title:'Nişan Alma',icon:'archery-aim',base:1000,desc:'Her seviye isabeti artırır.'},{title:'Yay Gücü',icon:'archery-bow',base:1100,desc:'Her seviye ok gücünü artırır.'},{title:'Rüzgâr Okuma',icon:'archery-wind',base:950,desc:'Rüzgâr etkisini azaltıp isabeti artırır.'},{title:'Son Atış',icon:'archery-last',base:1200,desc:'Son nişan düzeltmesiyle isabeti artırır.'}];
const activeUpgrades=()=>state.branch==='archery'?archeryUpgrades:state.branch==='weights'?weightUpgrades:state.branch==='longjump'?longJumpUpgrades:state.branch==='swim'?swimUpgrades:state.branch==='hurdles'?hurdleUpgrades:upgrades;
const upgradeLevels=()=>state.branch==='archery'?state.archeryLevels:state.branch==='weights'?state.weightLevels:state.branch==='longjump'?state.longJumpLevels:state.branch==='swim'?state.swimLevels:state.branch==='hurdles'?state.hurdleLevels:state.levels;
const equipmentItems=[{name:'Yarış Ayakkabısı',effect:'Genel hız',bonus:3,base:2000},{name:'Çıkış Bloğu',effect:'İlk 25 m hızı',bonus:4,base:1800},{name:'Koşu Forması',effect:'Son 50 m temposu',bonus:2.5,base:2200},{name:'Sprint Bilekliği',effect:'Son 20 m hızı',bonus:4,base:2000}];
const fmt=n=>n>=1e6?(n/1e6).toLocaleString('tr-TR',{maximumFractionDigits:1})+'M':n>=1e4?(n/1e3).toLocaleString('tr-TR',{maximumFractionDigits:1})+'K':Math.floor(n).toLocaleString('tr-TR');
const cost=i=>Math.round(activeUpgrades()[i].base*Math.pow(1.19,upgradeLevels()[i]-1));
const level=()=>1+Math.floor(state.xp/100);
const passiveIncome=()=>15+state.levels[4]*upgrades[4].income*(1+campusRank("stadium",0)*.05)+state.levels[5]*upgrades[5].income*(1+campusRank("stadium",1)*.05);
const income=()=>Math.round(passiveIncome()*(Date.now()<state.boostUntil?2:1));
const statValue=(i,next=0)=>state.branch==='archery'?'+'+((upgradeLevels()[i]+next-1)*[1.4,.8,.9,.6][i]).toLocaleString('tr-TR',{maximumFractionDigits:1})+'%':state.branch==='weights'?'+'+((upgradeLevels()[i]+next-1)*[2.5,.8,.9,1][i]).toLocaleString('tr-TR',{maximumFractionDigits:1})+'%':state.branch==='longjump'?'+'+((upgradeLevels()[i]+next-1)*[.7,.9,1.6,1.1][i]).toLocaleString('tr-TR',{maximumFractionDigits:1})+'%':activeUpgrades()[i].income?'+₺'+fmt(activeUpgrades()[i].income*(upgradeLevels()[i]+next))+'/sn':20+(upgradeLevels()[i]+next)*2+'%';
let inventoryTab='athletes',toastTimer,activeModal='',race=null,lastFrame=performance.now(),sinceSave=0,resultDelay=0,paused=false,audio;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function save(){state.last=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){if(storageOK)toast('Tarayıcı kaydı kapalı; ilerleme bu oturumda tutuluyor.');storageOK=false;}}
function beep(freq=600,duration=.08){if(!state.sound||state.soundVolume<=0)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(Math.max(.0001,.025*state.soundVolume),audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch(e){}}
function renderUpgrades(){ $('#upgrades').innerHTML=activeUpgrades().map((u,i)=>`<article class="upgrade"><div class="upgrade-top"><span class="upgrade-icon-box"><span class="art upgrade-icon ${state.branch==='swim'?'swim-icon':''}" data-art="${u.icon}"></span></span><div><h2>${u.title}</h2><span class="level" id="lv-${i}">Sv. ${upgradeLevels()[i]}</span></div><button class="info" data-info="${i}" aria-label="${u.title} hakkında">i</button></div><div class="stats"><span id="stat-${i}">${statValue(i)}</span><span class="arrow">➜</span><span class="next" id="next-${i}">${statValue(i,1)}</span></div><button class="green" data-upgrade="${i}"><span>Yükselt</span><span class="cost"><span class="art cost-icon" data-art="bank"></span><span id="cost-${i}">₺${fmt(cost(i))}</span></span></button></article>`).join('');arts($('#upgrades'));}
function update(){ $('#money').textContent=fmt(state.money);$('#gems').textContent=fmt(state.gems);$('#income').textContent='₺'+fmt(income());$('#level').textContent='Sv. '+level();$('#xp').style.width=state.xp%100+'%';$('#power').textContent=100+state.levels.slice(0,4).reduce((a,b)=>a+b-1,0)*12+(state.equipmentStars.reduce((a,b)=>a+b,0)+state.equipmentLegacy)*10+(state.camp-1)*10;$('#round').textContent=state.branch==='hurdles'||state.branch==='swim'?(race?.place||1)+' / 6':state.races+1;$('#auto').setAttribute('aria-pressed',state.auto);$('#auto').innerHTML='↻ Otomatik <b>'+(state.auto?'AÇIK':'KAPALI')+'</b>';const remain=state.boostUntil-Date.now(),cool=state.boostReady-Date.now();$('#boost').textContent=remain>0?'2x · '+Math.ceil(remain/1000)+' sn':cool>0?'2x · '+Math.ceil(cool/1000)+' sn':'2x Aktif Et';$('#boost').disabled=cool>0;$$('[data-upgrade]').forEach(b=>{const i=+b.dataset.upgrade;if(i>=activeUpgrades().length)return;b.disabled=state.money<cost(i)||upgradeLevels()[i]>=100;$('#lv-'+i).textContent='Sv. '+upgradeLevels()[i];$('#stat-'+i).textContent=statValue(i);$('#next-'+i).textContent=statValue(i,1);$('#cost-'+i).textContent=upgradeLevels()[i]>=100?'MAKS.':'₺'+fmt(cost(i));});$('#ach-dot').hidden=!achievements.some(a=>a.done()&&!state.claims.includes(a.id));if(state.branch==='longjump'){updateLongJumpHUD();$('#power').textContent=100+state.longJumpLevels.reduce((sum,n)=>sum+n-1,0)*12;}if(state.branch==='archery'){updateArcheryHUD();$('#power').textContent=100+state.archeryLevels.reduce((sum,n)=>sum+n-1,0)*12;}if(state.branch==='weights'){updateWeightHUD();$('#power').textContent=100+state.weightLevels.reduce((sum,n)=>sum+n-1,0)*12;}}
function upgrade(i){if(!Number.isInteger(i)||i<0||i>=activeUpgrades().length)throw Error('Geçersiz yükseltme');const levels=upgradeLevels(),item=activeUpgrades()[i];if(levels[i]>=100)return {ok:false,reason:'Maksimum seviye'};const price=cost(i);if(state.money<price){toast('Bu yükseltme için biraz daha gelir biriktir.');return{ok:false,reason:'Yetersiz para'};}state.money-=price;levels[i]++;state.xp+=5;save();update();beep(820);toast(item.title+' → Sv. '+levels[i]);return{ok:true,level:levels[i],money:Math.floor(state.money)};}
const todayKey=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dailyPrizes=[{icon:'💵',label:'₺10K',money:10000},{icon:'🎟️',label:'1 bilet',tickets:1},{icon:'💎',label:'10 elmas',gems:10},{icon:'💵',label:'₺25K',money:25000},{icon:'🎟️',label:'2 bilet',tickets:2},{icon:'💎',label:'25 elmas',gems:25},{icon:'🎁',label:'Büyük ödül',money:50000,gems:40,tickets:2}];
const dayClaimed=()=>state.daily&&new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(state.daily))===todayKey();
const wheelPrizes=[{label:'₺5K',money:5000},{label:'₺10K',money:10000},{label:'₺20K',money:20000},{label:'5 elmas',gems:5},{label:'10 elmas',gems:10},{label:'1 bilet',tickets:1}];
function grant(prize){state.money+=(prize.money||0);state.gems+=(prize.gems||0);state.spinTickets+=(prize.tickets||0);save();update();}
function rewardsMenu(open){$('#rewards-menu').hidden=!open;$('#rewards-trigger').setAttribute('aria-expanded',String(open));}
function selectNav(button){$$('.bottom button').forEach(item=>item.classList.toggle('selected',item===button));}
const achievements=[{id:'first',title:'İlk Yarış',detail:'1 yarış yap',done:()=>state.races>=1,reward:10000},{id:'fast-paws',title:'Hızlı Patiler',detail:'3 yarış kazan',done:()=>state.wins>=3,reward:25000},{id:'full-stand',title:'Dolu Tribün',detail:'Tribünü 5. seviyeye yükselt',done:()=>state.levels[4]>=5,reward:40000},{id:'ticket-office',title:'Bilet Gişesi',detail:'Bileti 3. seviyeye yükselt',done:()=>state.levels[5]>=3,reward:35000}];
renderUpgrades();
let runnerEls=[];
const lineup=()=>[state.selected,...animals.map((_,i)=>i).filter(i=>i!==state.selected)].slice(0,state.branch==='archery'||state.branch==='weights'||state.branch==='longjump'||state.branch==='hurdles'||state.branch==='swim'?6:4);
function runners(){const ids=lineup();$('#runners').innerHTML=ids.map(i=>{const a=animals[i];return`<div class="runner ${i===state.selected?'player cosmetic-'+state.selectedCosmetic:''}" aria-label="${a.name}" title="${a.name}"><span class="face" data-art="${a.art}"></span></div>`;}).join('');arts($('#runners'));runnerEls=$$('.runner').slice(0,ids.length);positionRunners(ids.map(()=>0));}
// Oval path follows the actual stadium art; lane offsets keep all athletes on the track.
function point(progress,lane){const rx=20-lane*2.25,ry=25-lane*3.4,cy=52.5,t=(progress%1)*6;let x,y;if(t<1){const a=-t*Math.PI/2;x=74+rx*Math.cos(a);y=cy+ry*Math.sin(a);}else if(t<2){x=74-(t-1)*48;y=cy-ry;}else if(t<4){const a=-Math.PI/2-(t-2)*Math.PI/2;x=26+rx*Math.cos(a);y=cy+ry*Math.sin(a);}else if(t<5){x=26+(t-4)*48;y=cy+ry;}else{const a=Math.PI/2-(t-5)*Math.PI/2;x=74+rx*Math.cos(a);y=cy+ry*Math.sin(a);}return{x,y};}
function positionRunners(ps){if(state.branch==='archery'){positionArcheryAvatars();return;}if(state.branch==='weights'){positionWeightAvatars();return;}if(state.branch==='longjump'){positionJumpAvatars();return;}ps.forEach((p,i)=>{const pos=state.branch==='swim'?{x:7.2+p*86,y:38+i*8}:state.branch==='hurdles'?{x:5.1+p*85,y:35.5+i*9.2}:point(p,i);runnerEls[i].style.left=pos.x+'%';runnerEls[i].style.top=pos.y+'%';runnerEls[i].classList[state.branch==='hurdles'&&race?.phase==='running'&&[.2,.42,.64,.84].some(h=>Math.abs(p-h)<.018)?'add':'remove']('jump');});}
function renderHurdles(){$('#risk-choice').hidden=state.branch!=='weights';const hurdle=state.branch==='hurdles',swim=state.branch==='swim',stadium=$('.stadium');stadium.classList[state.branch==='archery'?'add':'remove']('archery-mode');$('#archery-hud').hidden=state.branch!=='archery';stadium.classList[state.branch==='weights'?'add':'remove']('weights-mode');$('#weight-hud').hidden=state.branch!=='weights';stadium.classList[state.branch==='longjump'?'add':'remove']('longjump-mode');stadium.classList[hurdle?'add':'remove']('hurdle-mode');stadium.classList[swim?'add':'remove']('swim-mode');$('#stadium-art').src=swim?'assets/swim-arena.png':hurdle?'assets/hurdle-arena.png':'assets/stadium.png';$('#stadium-art').alt=swim?'Hayvan seyircili altı kulvarlı yüzme havuzu':hurdle?'Hayvan tribünlü altı kulvarlı engelli koşu pisti':'Çizgi film tarzında kırmızı koşu pisti';$('#hurdles').innerHTML=hurdle?Array.from({length:6},(_,lane)=>[24,44,64,83].map(x=>`<span class="hurdle" style="left:${x}%;top:${35.5+lane*9.2}%"></span>`).join('')).join(''):'';$('#branch-name').textContent=swim?'YÜZME':hurdle?'ENGELLİ KOŞU':'100 METRE';$('.branch .art').dataset.art=swim?'swim-wave':hurdle?'speed':'shoe';paintArt($('.branch .art'),swim?'swim-wave':hurdle?'speed':'shoe');$('#timer').textContent=hurdle||swim?'◴ 00:00':'HAZIR';if(!race){$('#race-call>span').textContent=swim?'Altı sporcu havuzda, yarışa hazır!':hurdle?'Altı sporcu, dört engel: başlangıç çizgisine gel!':'İlk madalyan seni bekliyor!';$('#race-status').textContent=swim?'Yüzme hazır. Kronometre çıkışta başlar.':hurdle?'Engelli koşu hazır. Kronometre çıkışta başlar.':'Çitanı geliştir, başlangıç çizgisine gel.';}if(state.branch==='longjump'){ $('#stadium-art').src='assets/jump-arena.png';$('#stadium-art').alt='Tek kulvarlı uzun atlama pisti, sağda kum havuzu, altta bekleme bankı';$('#branch-name').textContent='UZUN ATLAMA';$('.branch .art').dataset.art='jump-start';paintArt($('.branch .art'),'jump-start');$('#timer').textContent='DENEME';$('#start').textContent='Atlayışa Başla ▶';$('#race-status').textContent='Sporcular sırayla atlar · Bayraklara dokunarak mesafeyi gör.';renderJumpFlags();}else{$('#jump-flags').innerHTML='';}if(state.branch==='weights')renderWeightArena();if(state.branch==='archery')renderArcheryArena();runners();update();}
function selectBranch(branch){if(race){toast('Branşı yarış bitince değiştirebilirsin.');return;}if(!['sprint','hurdles','swim','longjump','weights','archery'].includes(branch))return;if(branch==='longjump'&&state.branch!=='longjump')jumpCompleted=[];if(branch==='weights'&&state.branch!=='weights')weightCompleted=[];if(branch==='archery'&&state.branch!=='archery')archeryCompleted=[];state.branch=branch;clearMove();resultDelay=0;renderUpgrades();renderHurdles();$('#race-call').hidden=false;$('#race-call>span').textContent=branch==='swim'?'Altı sporcu havuzda, yarışa hazır!':branch==='hurdles'?'Altı sporcu, dört engel: başlangıç çizgisine gel!':'İlk madalyan seni bekliyor!';$('#start').textContent='Yarışa Başla ▶';$('#race-status').textContent=branch==='swim'?'Yüzme hazır. Kronometre çıkışta başlar.':branch==='hurdles'?'Engelli koşu hazır. Kronometre çıkışta başlar.':'Çitanı geliştir, başlangıç çizgisine gel.';if(branch==='longjump'){$('#start').textContent='Atlayışa Başla ▶';$('#race-status').textContent='Sporcular sırayla atlar · Bayraklara dokunarak mesafeyi gör.';}if(branch==='archery'){$('#start').textContent='Atışa Başla ▶';$('#race-status').textContent='Sporcular sırayla atış yapar · En yüksek puan kazanır.';}if(branch==='weights'){$('#start').textContent='Kaldırışa Başla ▶';$('#race-status').textContent='Sporcular sırayla kaldırır · En yüksek başarılı kilo kazanır.';}$('#modal').close();save();}
function beginRace(){if(state.branch==='archery')return beginArchery();if(state.branch==='weights')return beginWeights();if(state.branch==='longjump')return beginLongJump();if(race||paused)return{ok:false,reason:'Yarış zaten sürüyor'};resultDelay=0;const base=9.3,ids=lineup(),n=ids.length;race={branch:state.branch,phase:'countdown',countdown:3,elapsed:0,progress:Array(n).fill(0),times:Array(n).fill(null),ids,playerLane:ids.indexOf(state.selected),place:1,speeds:ids.map(id=>id===state.selected?base*animals[id].speed*specialty(state.branch,id):base*(.96+Math.random()*.12+Math.min(state.wins*.003,.12))),levels:[...state.levels],hurdleLevels:[...state.hurdleLevels],swimLevels:[...state.swimLevels],equipmentStars:[...state.equipmentStars],equipmentLegacy:state.equipmentLegacy,campus:[0,1,2].map(i=>campusRank(state.branch,i)),trainingCard:consumeTrainingCard(state.branch)};runners();$('.stadium').classList.remove('idle');$('#race-call').hidden=true;$('#live-tag').hidden=false;$('#timer').textContent=state.branch==='hurdles'||state.branch==='swim'?'◴ 00:00':'3';$('#race-status').textContent='Hazırlan… 3, 2, 1!';if(state.branch==='sprint')offerMove('sprint',2.4,'Çıkış yap!');beep(400);return{ok:true};}
function finishRace(){const playerLane=race.playerLane,times=race.times.map((time,i)=>({i,time:time??race.elapsed})).sort((a,b)=>a.time-b.time);const place=times.findIndex(x=>x.i===playerLane)+1,time=times.find(x=>x.i===playerLane).time;state.races++;state.xp+=place===1?30:15;if(state.races%5===0){state.chests++;state.skillPoints++;}if(place===1)state.wins++;if(place<=3)state.medals++;recordTournament(state.branch,place);state.best=state.best===null?time:Math.min(state.best,time);const reward=Math.round((place===1?1250:place===2?850:place===3?650:400)*(1+Math.floor(state.races/10)*.1)*(1+campusRank("stadium",2)*.03));state.money+=reward;clearMove();race=null;$('.stadium').classList.add('idle');$('#live-tag').hidden=true;$('#timer').textContent=state.branch==='hurdles'||state.branch==='swim'?'◴ '+Math.floor(time/60).toString().padStart(2,'0')+':'+Math.floor(time%60).toString().padStart(2,'0'):time.toFixed(2)+' sn';$('#race-status').textContent=`${place}. oldun · +₺${fmt(reward)} · ${time.toFixed(2)} sn`;toast(`${place===1?'🏆 Zafer!':place<=3?'🏅 Madalya!':'🏁 Yarış bitti'} ${place}. sıra · +₺${fmt(reward)}`);beep(place===1?960:540,.18);resultDelay=state.auto?4:0;$('#race-call').hidden=false;$('#race-call>span').textContent=state.auto?'Yeni yarış 4 saniye içinde':`${place}. sıra · ${time.toFixed(2)} sn`;$('#start').textContent='Yeniden Yarış ▶';save();update();}
function tick(now){
 const dt=Math.min((now-lastFrame)/1000,.1);lastFrame=now;
 if(!paused){tickMove(dt);
  state.money+=income()*dt;
  if(race){
   if(race.branch==='archery')advanceArchery(dt);
   else if(race.branch==='weights')advanceWeights(dt);
   else if(race.branch==='longjump')advanceLongJump(dt);
   else if(race.phase==='countdown'){
    const prev=Math.ceil(race.countdown);race.countdown-=dt;
    if(state.branch==='sprint')$('#timer').textContent=Math.max(1,Math.ceil(race.countdown));
    if(Math.ceil(race.countdown)!==prev)beep(500);
    if(race.countdown<=0){race.manualBonus=state.branch==='sprint'?moveQuality()*.06:0;clearMove();race.moveOffered=false;race.phase='running';race.elapsed=0;$('#timer').textContent=state.branch==='hurdles'||state.branch==='swim'?'◴ 00:00':'0.00 sn';$('#race-status').textContent='Yarış sürüyor · '+animals[state.selected].name+' takımını temsil ediyor';beep(900,.15);}
   }else{
    race.elapsed+=dt;
    if((state.branch==='hurdles'||state.branch==='swim')&&!race.moveOffered&&race.progress[race.playerLane]>.4){race.moveOffered=true;offerMove(state.branch,1.5,state.branch==='hurdles'?'Engeli geç!':'Güçlü kulaç!');}if(activeMove?.elapsed>=activeMove?.duration){race.manualBonus=moveQuality()*.06;clearMove();}race.progress=race.progress.map((p,i)=>{
     if(p>=1)return 1;
     let speed=race.speeds[i];if(i===race.playerLane)speed*=1+(race.manualBonus||0)+(race.trainingCard?.03:0);
     if(state.branch==='hurdles'){
      const h=race.hurdleLevels;
      const nearHurdle=[.2,.42,.64,.84].some(x=>Math.abs(p-x)<.023);
      if(nearHurdle)speed*=i===race.playerLane?Math.min(.96,.55+(h[0]-1)*.025):.58;
      if(i===race.playerLane){speed*=1+race.campus[1]*.01+(h[1]-1)*.01+(race.equipmentStars[0]+race.equipmentLegacy)*.02;if(p>.5)speed*=1+(h[2]-1)*.012;if(p>.84)speed*=1+race.campus[2]*.01+(h[3]-1)*.02;if(nearHurdle)speed*=1+race.campus[0]*.025;}
     }else if(state.branch==='swim'){
      if(i===race.playerLane){const l=race.swimLevels;speed*=1+race.campus[1]*.01+(l[1]-1)*.012;if(p<.25)speed*=1+race.campus[0]*.01+(l[0]-1)*.02;if(p>.5)speed*=1+race.campus[2]*.01+(l[2]-1)*.015;if(p>.75)speed*=1+(l[3]-1)*.017;speed*=1+(race.equipmentStars[0]+race.equipmentLegacy)*.012;}
     }else if(i===race.playerLane){
      const l=race.levels;speed*=1+race.campus[1]*.01;
      if(p<.25)speed*=1+race.campus[0]*.01;if(p>.8)speed*=1+race.campus[2]*.01;
      speed*=1+(l[1]-1)*.01+(race.equipmentStars[0]+race.equipmentLegacy)*.03;
      if(p<.25)speed*=(1+(l[0]-1)*.02)*(1+race.equipmentStars[1]*.04);
      if(p>.5)speed*=(1+(l[2]-1)*.015)*(1+race.equipmentStars[2]*.025);
      if(p>.8)speed*=(1+(l[3]-1)*.02)*(1+race.equipmentStars[3]*.04);
     }
     const next=p+speed*dt/100;
     if(next>=1)race.times[i]=race.elapsed;
     return Math.min(1,next);
    });
    if(state.branch==='hurdles'||state.branch==='swim')race.place=1+race.progress.reduce((count,p,i)=>count+(i!==race.playerLane&&p>race.progress[race.playerLane]?1:0),0);
    positionRunners(race.progress);
    $('#timer').textContent=state.branch==='hurdles'||state.branch==='swim'?'◴ '+Math.floor(race.elapsed/60).toString().padStart(2,'0')+':'+Math.floor(race.elapsed%60).toString().padStart(2,'0'):race.elapsed.toFixed(2)+' sn';
    if(race.progress.every(p=>p>=1))finishRace();
   }
  }else if(resultDelay>0&&state.auto){resultDelay-=dt;$('#race-call>span').textContent='Yeni yarış '+Math.max(1,Math.ceil(resultDelay))+' saniye içinde';if(resultDelay<=0)beginRace();}
 }
 sinceSave+=dt;if(sinceSave>.4)update();if(sinceSave>=5){sinceSave=0;save();}requestAnimationFrame(tick);
}
function panel(title,html){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;arts($('#modal-content'));if(!$('#modal').open)$('#modal').showModal();}
function openPanel(key){rewardsMenu(false);activeModal=key;$('#modal').classList.remove('reward-dialog','exact-dialog','exact-ach-dialog','exact-daily-dialog','settings-dialog');switch(key){case'race':$('#modal').close();break;case'profile':panel('Profil',`<p>Takımının adı</p><input id="team-name" class="name-input" maxlength="24" aria-label="Takım adı"><button class="modal-action" id="save-name">Kaydet</button><div class="modal-stat"><div><b>${level()}</b><small>Seviye</small></div><div><b>${state.races}</b><small>Yarış</small></div><div><b>${state.wins}</b><small>Zafer</small></div></div><p class="muted">${storageOK?'İlerlemen otomatik olarak bu tarayıcıda saklanır.':'Tarayıcı kaydı kullanılamıyor; sayfayı kapatırsan ilerleme kaybolabilir.'}</p>`);$('#team-name').value=state.name;break;
case'inventory':panel('Envanter',inventoryHTML());break;
case'chests':panel('Spor Çantaları',chestHTML());break;
case'cosmetics':panel('Avatar Çerçeveleri',`<p>Yeni çerçeveler Şampiyon Çantası'ndan çıkabilir.</p>${state.cosmetics.map(i=>`<div class="row"><span>✨ ${cosmeticNames[i]}</span><button data-cosmetic="${i}">${state.selectedCosmetic===i?'Seçili':'Seç'}</button></div>`).join('')||'<p>Henüz çerçeve kazanmadın.</p>'}`);break;
case'campus':openCampus();break;
case'achievements':panel('Başarımlar',achievementPanelHTML());$('#modal').classList.add('exact-dialog','exact-ach-dialog');break;
case'daily-rewards':panel('Günlük Ödül',dailyPanelHTML());$('#modal').classList.add('exact-dialog','exact-daily-dialog');break;
case'wheel':panel('Çarkıfelek',`<div class="wheel-art" aria-hidden="true">🎡</div><p class="wheel-copy">Günlük ücretsiz çeviriş ${state.spinDate===todayKey()?'kullanıldı':'hazır'}. Ek bilet: ${state.spinTickets}</p><button class="modal-action full" id="spin-wheel" ${state.spinDate===todayKey()&&state.spinTickets<1?'disabled':''}>${state.spinDate===todayKey()?'1 biletle çevir':'Ücretsiz çevir'}</button><p class="reward-note">₺5K–₺20K, elmas veya çark bileti kazan.</p>`);$('#modal').classList.add('reward-dialog');break;
case'settings':panel('Ayarlar',settingsHTML());$('#modal').classList.add('settings-dialog');break;
case'team':panel('Hayvan Takımın',animals.map((a,i)=>`<div class="row ${state.races<a.unlock?'locked':''}"><span class="art face-art" data-art="${a.art}"></span><div>${a.name}<small>${a.trait} · Uzmanlık: ${specialtyLabel(i)}</small></div><button data-select="${i}" ${state.races<a.unlock||!!race?'disabled':''}>${state.races<a.unlock?a.unlock+' yarış':state.selected===i?'Seçili':'Seç'}</button></div>`).join('')+(race?'<p class="muted">Sporcunu yarış bitince değiştirebilirsin.</p>':''));break;
case'league':panel('Çaylaklar Ligi',`<p>Her 10 yarış bir sezon. Madalyalar ve rekorlar takımının ilerlemesini gösterir.</p><div class="modal-stat"><div><b>${Math.floor(state.races/10)+1}</b><small>Sezon</small></div><div><b>${state.races%10}/10</b><small>Yarış</small></div><div><b>${state.medals}</b><small>Madalya</small></div></div><div class="row"><span>En iyi derecen</span><b>${state.best?state.best.toFixed(2)+' sn':'Henüz yok'}</b></div><div class="row"><span>Toplam zafer</span><b>${state.wins}</b></div><p class="muted">Rakipler bilgisayar tarafından yönetilir.</p>`);break;
case'tournament':panel('Üç Yarışlık Kupa',tournamentHTML());break;
case'equipment':inventoryTab='equipment';openPanel('inventory');break;
case'camp':panel('Antrenman Kampı',`<p>Kampı büyüt; takım gücünü ve sporcularının gelişimini artır.</p><div class="modal-stat"><div><b>${state.camp}</b><small>Kamp seviyesi</small></div><div><b>${100+(state.camp-1)*10}</b><small>Kamp gücü</small></div><div><b>+10</b><small>Sonraki seviye</small></div></div><button class="modal-action full" id="buy-camp" ${state.money<campCost()?'disabled':''}>Kampı geliştir · ₺${fmt(campCost())}</button>`);break;
case'shop':panel('Mağaza',`<p>Oyun içi ödüller. Gerçek para ile satın alma yok.</p><div class="row"><div>Günlük ödül<small>7 günlük ödül takvimi</small></div><button id="daily">Aç</button></div><div class="row"><div>Sponsor paketi<small>+₺10.000 · 5 elmas</small></div><button id="buy-coins" ${state.gems<5?'disabled':''}>Al</button></div>`);break;
case'branches':panel('Spor Branşları',`<p>Oynamak istediğin yarışı seç.</p><button class="modal-action full" data-open="tournament">🏆 Üç Yarışlık Kupa</button><div class="row"><span>100 metre koşu</span><button data-branch="sprint" ${race?'disabled':''}>${state.branch==='sprint'?'Seçili':'Oyna'}</button></div><div class="row"><span>Engelli koşu</span><button data-branch="hurdles" ${race?'disabled':''}>${state.branch==='hurdles'?'Seçili':'Oyna'}</button></div><div class="row"><span>Yüzme</span><button data-branch="swim" ${race?'disabled':''}>${state.branch==='swim'?'Seçili':'Oyna'}</button></div><div class="row"><span>Uzun atlama</span><button data-branch="longjump" ${race?'disabled':''}>${state.branch==='longjump'?'Seçili':'Oyna'}</button></div><div class="row"><span>Halter</span><button data-branch="weights" ${race?'disabled':''}>${state.branch==='weights'?'Seçili':'Oyna'}</button></div><div class="row"><span>Okçuluk</span><button data-branch="archery" ${race?'disabled':''}>${state.branch==='archery'?'Seçili':'Oyna'}</button></div>`);break;
}}
const equipmentCost=i=>Math.round(equipmentItems[i].base*[1,2.5,6][state.equipmentStars[i]]);
function buyEquipment(i,useParts=false){if(!Number.isInteger(i)||i<0||i>=equipmentItems.length)return false;if(state.equipmentStars[i]>=3)return false;const price=equipmentCost(i);if(useParts){if(state.equipmentParts<5)return false;state.equipmentParts-=5;}else{if(state.money<price)return false;state.money-=price;}state.equipmentStars[i]++;state.xp+=5;save();update();toast(equipmentItems[i].name+' → '+state.equipmentStars[i]+' yıldız');return true;}
function inventoryHTML(){const tabs=[['athletes','Sporcular'],['equipment','Ekipman'],['items','Eşyalar']];const header='<div class="inventory-tabs">'+tabs.map(([id,label])=>`<button class="${inventoryTab===id?'active':''}" data-inventory-tab="${id}" aria-pressed="${inventoryTab===id}">${label}</button>`).join('')+'</div>';if(inventoryTab==='athletes')return header+animals.map((a,i)=>`<div class="inventory-card ${state.races<a.unlock?'locked':''}"><span class="art inventory-art" data-art="${a.art}"></span><div><b>${a.name}</b><small>${a.trait} · Uzmanlık: ${specialtyLabel(i)}</small></div><button class="modal-action" data-select="${i}" ${state.races<a.unlock||!!race?'disabled':''}>${state.races<a.unlock?a.unlock+' yarış':state.selected===i?'Seçili':'Seç'}</button></div>`).join('');if(inventoryTab==='equipment')return header+'<p class="equipment-intro">Her ekipman en fazla 3 yıldıza yükselir. Etkileri sonraki yarışta uygulanır.</p><div class="equipment-list">'+equipmentItems.map((item,i)=>{const stars=state.equipmentStars[i];return `<div class="equipment-card"><span class="equipment-icon" style="background-position:${i*100/3}% center"></span><div class="equipment-copy"><b>${item.name}</b><span class="equipment-stars" aria-label="${stars} / 3 yıldız">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</span><small>${item.effect}: +%${(stars*item.bonus).toLocaleString('tr-TR')}</small></div>${stars<3&&state.equipmentParts>=5?`<button data-parts-upgrade="${i}">5 parça</button>`:''}<button data-equipment-upgrade="${i}" ${stars>=3||state.money<equipmentCost(i)?'disabled':''}>${stars>=3?'MAKS.':'₺'+fmt(equipmentCost(i))}</button></div>`}).join('')+'</div>';return header+`<div class="inventory-card"><span class="item-emoji">⚙️</span><div><b>Ekipman parçası ×${state.equipmentParts}</b><small>5 parça ile bir ekipmanı yıldızla geliştir</small></div></div><div class="inventory-card"><span class="item-emoji">🎫</span><div><b>Antrenman kartları</b><small>${Object.entries(state.trainingCards).filter(([,n])=>n>0).map(([id,n])=>branchLabel(id)+' ×'+n).join(', ')||'Henüz yok'} · Sonraki ilgili yarışta otomatik kullanılır</small></div></div><div class="inventory-card"><span class="item-emoji">✨</span><div><b>Avatar çerçeveleri</b><small>${state.cosmetics.length} / 4 açık · Tekrarı parçaya dönüşür</small></div><button data-open="cosmetics">Seç</button></div><div class="inventory-card"><span class="art inventory-art" data-art="ticket"></span><div><b>Çark bileti ×${state.spinTickets}</b><small>Ödül çarkında bir kez kullanılır</small></div><button class="modal-action" data-open="wheel">Aç</button></div><div class="inventory-card"><span class="item-emoji">🎁</span><div><b>Spor Çantaları ×${state.chests+state.cupChests+state.championChests}</b><small>Normal ${state.chests} · Kupa ${state.cupChests} · Şampiyon ${state.championChests}</small></div><button data-open="chests">Aç</button></div><div class="inventory-card"><span class="item-emoji">⚡</span><div><b>2x gelir kuponu ×${state.boostTokens}</b><small>30 saniye boyunca geliri ikiye katlar</small></div><button id="use-boost-token" ${state.boostTokens<1?'disabled':''}>Kullan</button></div>`;}
const campCost=()=>Math.round(2500*Math.pow(1.5,state.camp-1));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.chestOpen){if(openChest(b.dataset.chestOpen))openPanel('chests');return;}if(b.dataset.chestChoice!==undefined){const prize=chooseChest(+b.dataset.chestChoice);if(prize){activeModal='chests-result';panel('Çanta Açıldı',`<div class="chest-reveal"><span>${prize.icon}</span><strong>${prize.label}</strong></div><button class="modal-action full" data-open="inventory">Envantere dön</button>`);}return;}if(b.dataset.partsUpgrade!==undefined){if(buyEquipment(+b.dataset.partsUpgrade,true))openPanel('inventory');return;}if(b.dataset.cosmetic!==undefined){const i=+b.dataset.cosmetic;if(state.cosmetics.includes(i)){state.selectedCosmetic=i;save();runners();openPanel('cosmetics');}return;}if(b.id==='risk-choice'){if(race)return;state.weightRisk=state.weightRisk==='record'?'safe':'record';b.textContent=state.weightRisk==='record'?'Rekor denemesi':'Güvenli kilo';save();return;}if(b.id==='skill-button'){tapMove();return;}if(b.id==='tournament-start'){if(startTournament())toast('Kupa başladı! Üç yarışta iki madalya kazan.');openPanel('tournament');return;}if(b.dataset.branch){selectBranch(b.dataset.branch);return;}if(b.id==='rewards-trigger'){selectNav(b);rewardsMenu($('#rewards-menu').hidden);return;}if(b.dataset.inventoryTab){inventoryTab=b.dataset.inventoryTab;openPanel('inventory');return;}if(b.dataset.equipmentUpgrade!==undefined){if(buyEquipment(+b.dataset.equipmentUpgrade))openPanel('inventory');return;}if(b.dataset.open){if(b.closest('.bottom'))selectNav(b);beep(620,.04);openPanel(b.dataset.open);}if(b.dataset.upgrade!==undefined){const result=upgrade(+b.dataset.upgrade);if(result.ok&&activeModal==='campus')openPanel('campus');}if(b.dataset.info!==undefined){const u=activeUpgrades()[+b.dataset.info];panel(u.title,`<p>${u.desc}</p><p class="muted">Yükseltmelerin yarış etkisi bir sonraki yarışta uygulanır. Karttaki yüzde, antrenman gelişimini gösterir.</p>`);}if(b.dataset.claim){const a=achievements.find(x=>x.id===b.dataset.claim);if(a?.done()&&!state.claims.includes(a.id)){state.claims.push(a.id);state.money+=a.reward;if(['fast-paws','full-stand'].includes(a.id))state.championChests++;save();update();openPanel('achievements');toast('Başarım ödülü alındı!');}}if(b.dataset.select!==undefined){const i=+b.dataset.select;if(!race&&animals[i]&&state.races>=animals[i].unlock){state.selected=i;runners();save();openPanel(activeModal==='inventory'?'inventory':'team');toast(animals[i].name+' takım liderin oldu.');}}switch(b.id){case'start':beginRace();break;case'boost':if(Date.now()>=state.boostReady){state.boostUntil=Date.now()+30000;state.boostReady=Date.now()+90000;save();update();toast('30 saniye boyunca gelir iki katı!');}break;case'auto':state.auto=!state.auto;if(!state.auto)resultDelay=0;save();update();break;case'close':case'exact-close':$('#modal').close();break;case'save-name':state.name=$('#team-name').value.trim().slice(0,24)||'Pati Takımı';save();toast('Takım adı kaydedildi.');break;case'use-boost-token':if(state.boostTokens>0){state.boostTokens--;state.boostUntil=Math.max(Date.now(),state.boostUntil)+30000;save();update();openPanel('inventory');toast('2x gelir 30 saniye uzatıldı!');}break;case'buy-camp':if(state.money>=campCost()){state.money-=campCost();state.camp++;save();update();openPanel(activeModal==='campus'?'campus':'camp');}break;case'daily':openPanel('daily-rewards');break;case'claim-daily':if(!dayClaimed()){const prize=dailyPrizes[state.dailyStep%7];state.daily=Date.now();state.dailyStep++;grant(prize);openPanel('daily-rewards');toast(prize.label+' kazandın!');}break;case'spin-wheel':if(state.spinDate!==todayKey()||state.spinTickets>0){if(state.spinDate===todayKey())state.spinTickets--;else state.spinDate=todayKey();const prize=wheelPrizes[Math.floor(Math.random()*wheelPrizes.length)];grant(prize);openPanel('wheel');toast('Çark ödülün: '+prize.label);}break;case'buy-coins':if(state.gems>=5){state.gems-=5;state.money+=10000;save();update();openPanel('shop');toast('+₺10.000 sponsor geliri!');}break;case'settings-support':panel('Destek','<p>İlerlemen bu cihazdaki tarayıcıya otomatik kaydedilir. Müzik ve ses düzeylerini Ayarlar bölümünden değiştirebilirsin.</p><p>Titreşim, tarayıcı ve cihaz destekliyorsa çalışır.</p><button class="modal-action full" data-open="settings">Ayarlara dön</button>');$('#modal').classList.remove('exact-dialog','settings-dialog');break;case'reset-ask':$('#modal').classList.remove('exact-dialog','settings-dialog');panel('İlerleme sıfırlansın mı?','<p>Bu cihazdaki bütün yarışlar, seviyeler ve ödüller silinecek.</p><button class="modal-action full" id="reset-cancel">Vazgeç</button><button class="modal-action full" id="reset-confirm">Evet, sıfırla</button>');break;case'reset-cancel':openPanel('settings');break;case'reset-confirm':state=initial();clearMove();race=null;resultDelay=0;paused=false;save();renderUpgrades();renderHurdles();update();$('#timer').textContent='HAZIR';$('#race-call').hidden=false;$('#race-call>span').textContent='İlk madalyan seni bekliyor!';$('#live-tag').hidden=true;$('#modal').close();toast('Yeni takımın hazır.');break;}});
document.addEventListener('change',e=>{if(e.target.id==='sound-setting')state.sound=e.target.checked;if(e.target.id==='auto-setting')state.auto=e.target.checked;if(e.target.id==='pause-setting'){paused=e.target.checked;$('#race-status').textContent=paused?'Oyun duraklatıldı.':'Oyun devam ediyor.';}save();update();});
document.addEventListener('click',e=>{if(!e.target.closest('#rewards-menu, #rewards-trigger'))rewardsMenu(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')rewardsMenu(false);});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
let hiddenAt=0;document.addEventListener('visibilitychange',()=>{if(document.hidden){save();hiddenAt=Date.now();}else{if(hiddenAt&&!paused){state.money+=Math.min(LIMIT,(Date.now()-hiddenAt)/1000)*passiveIncome();hiddenAt=0;}lastFrame=performance.now();update();}});window.addEventListener('pagehide',save);
const away=Math.min(LIMIT,Math.max(0,(Date.now()-Number(state.last))/1000));if(away>60){const earned=Math.floor(away*passiveIncome());state.money+=earned;setTimeout(()=>toast('Tekrar hoş geldin! Çevrimdışı gelir: ₺'+fmt(earned)),700);}
renderHurdles();update();save();requestAnimationFrame(tick);
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_game_state',title:'Oyun durumunu oku',description:'Takımın mevcut parasını, yükseltmelerini ve yarış durumunu okur.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({money:Math.floor(state.money),levels:[...state.levels],races:state.races,wins:state.wins,racing:!!race})});document.modelContext.registerTool({name:'upgrade_athlete',title:'Sporcuyu geliştir',description:'Oyundaki parayı harcayarak seçilen yeteneği bir seviye yükseltir.',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:0,maximum:3}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>upgrade(input.index)});}catch(e){}}

function settingsIcon(name){
 const paths={music:'<path fill="#ffcc20" d="M23 34V12l25-5v23l-8 2V17l-9 2v19c0 12-19 15-19 4 0-6 6-9 11-8Z"/>',sound:'<path fill="#42baff" d="M9 25h10L34 12v40L19 39H9Z"/><path d="M42 23q10 9 0 18m7-26q17 17 0 34" fill="none" stroke="#ffc72a"/>',vibration:'<rect x="20" y="8" width="26" height="48" rx="5" fill="#35adf5"/><path d="M27 14h12M30 49h6M11 19l-5 7 5 7-5 7m48-21 5 7-5 7 5 7" fill="none"/>',pause:'<circle cx="32" cy="32" r="26" fill="#1aabf1"/><path d="M23 20h6v24h-6zm12 0h6v24h-6z" fill="white"/>',save:'<path d="M15 49C-1 45 3 26 17 25 17 8 40 7 45 23c20-1 22 26 5 26Z" fill="#a9e7ff"/><path d="m23 34 7 7 15-16" fill="none" stroke="#1acb24" stroke-width="7"/>',support:'<rect x="7" y="13" width="50" height="39" rx="6" fill="#eaf6ff"/><path d="m9 17 23 18 23-18" fill="#ff6256"/>',reset:'<path d="M48 17A23 23 0 1 0 52 44l-10-5A12 12 0 1 1 40 25l-9 2 25 7V9Z" fill="#63df24"/>'};
 if(name==='shoe')return '<span class="art prefs-icon" data-art="shoe" aria-hidden="true"></span>';
 return `<svg class="prefs-icon" viewBox="0 0 64 64" aria-hidden="true" fill="none" stroke="#0c2034" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><defs><linearGradient id="prefs-gold" x2=".3" y2="1"><stop stop-color="#fff381"/><stop offset=".5" stop-color="#ffcf27"/><stop offset="1" stop-color="#f2a509"/></linearGradient><linearGradient id="prefs-blue" x2=".8" y2="1"><stop stop-color="#bdeaff"/><stop offset=".55" stop-color="#70b6df"/><stop offset="1" stop-color="#3981b2"/></linearGradient></defs>${paths[name].replaceAll('fill="#ffcc20"','fill="url(#prefs-gold)"').replaceAll('fill="#42baff"','fill="url(#prefs-blue)"').replaceAll('fill="#35adf5"','fill="url(#prefs-blue)"')}</svg>`;
}
function settingsHTML(){
 const toggle=(id,label,value)=>`<label class="prefs-switch"><input type="checkbox" id="${id}" aria-label="${label}" ${value?'checked':''}><span class="prefs-switch-face"><span class="prefs-switch-text">${value?'AÇIK':'KAPALI'}</span></span></label>`;
 const range=(id,label,value)=>`<input class="prefs-range" style="--fill:${value*100}%" type="range" min="0" max="100" value="${Math.round(value*100)}" id="${id}" aria-label="${label}">`;
 const row=(icon,label,control)=>`<div class="prefs-row">${settingsIcon(icon)}<span class="prefs-label">${label}</span>${control}</div>`;
 return `<section class="prefs-panel" aria-labelledby="prefs-title"><header class="prefs-heading"><h2 id="prefs-title">AYARLAR</h2><button class="prefs-close" id="exact-close" aria-label="Ayarları kapat">×</button></header><div class="prefs-body"><section class="prefs-section" aria-labelledby="prefs-audio"><h3 id="prefs-audio">SES</h3>${row('music','MÜZİK',range('music-volume','Müzik',state.musicVolume))}${row('sound','SES',range('sound-volume','Ses',state.sound?state.soundVolume:0))}${row('vibration','TİTREŞİM',toggle('vibration-setting','Titreşim',state.vibration))}</section><section class="prefs-section" aria-labelledby="prefs-game"><h3 id="prefs-game">OYUN</h3>${row('shoe','OTOMATİK YARIŞ',toggle('auto-setting','Otomatik yarış',state.auto))}${row('pause','OYUNU DURAKLAT',toggle('pause-setting','Oyunu duraklat',paused))}</section><section class="prefs-section" aria-labelledby="prefs-save"><h3 id="prefs-save">KAYIT</h3>${row('save','CİHAZ KAYDI',`<span class="prefs-status ${storageOK?'':'unavailable'}" role="status">${storageOK?'AKTİF':'KAPALI'}</span>`)}</section><footer class="prefs-actions"><button id="settings-support">${settingsIcon('support')}<span>DESTEK</span></button><button id="reset-ask">${settingsIcon('reset')}<span>İLERLEMEYİ<br>SIFIRLA</span></button></footer><small class="prefs-version">SÜRÜM 1.0</small></div></section>`;
}
let musicTimer, musicStep=0;
function musicTick(){if(!audio||document.hidden||paused||state.musicVolume<=0)return;const notes=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=notes[musicStep++%notes.length];g.gain.setValueAtTime(.0001,audio.currentTime);g.gain.exponentialRampToValueAtTime(Math.max(.0001,.016*state.musicVolume),audio.currentTime+.03);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.4);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.45);}
function startMusic(){try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();if(!musicTimer)musicTimer=setInterval(musicTick,500);}catch{}}
document.addEventListener('pointerdown',startMusic,{once:true});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='music-volume'||t.id==='sound-volume'){const value=Number(t.value)/100;t.style.setProperty('--fill',t.value+'%');if(t.id==='music-volume'){state.musicVolume=value;startMusic();}else{state.soundVolume=value;state.sound=value>0;beep();}save();}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='vibration-setting'){state.vibration=t.checked;if(state.vibration&&navigator.vibrate)navigator.vibrate(40);}if(t.closest&&t.closest('.prefs-switch'))t.nextElementSibling.querySelector('.prefs-switch-text').textContent=t.checked?'AÇIK':'KAPALI';save();});
document.addEventListener('click',e=>{if(state.vibration&&e.target.closest('button')&&navigator.vibrate)navigator.vibrate(12);});

function achievementPanelHTML(){const values=[state.races,state.wins,state.levels[4],state.levels[5]],goals=[1,3,5,3],tops=[30.7,47,63.2,79.4];return `<div class="exact-panel exact-ach"><img src="assets/achievements-panel-exact.png" alt="Başarımlar"><button class="exact-close" id="exact-close" aria-label="Kapat"></button><progress class="achievement-total" value="${state.claims.length}" max="${achievements.length}" aria-label="Alınan başarımlar"></progress><span class="exact-ach-count">${state.claims.length} / ${achievements.length}</span>${achievements.map((a,i)=>`<div class="achievement-progress" style="top:${tops[i]+2}%"><progress value="${Math.min(values[i],goals[i])}" max="${goals[i]}" aria-label="${a.title}"></progress><span>${Math.min(values[i],goals[i])} / ${goals[i]}</span></div><button class="exact-ach-action ${state.claims.includes(a.id)?'taken':a.done()?'ready':'unready'}" data-claim="${a.id}" style="top:${tops[i]}%" aria-label="${a.title}: ${state.claims.includes(a.id)?'Alındı':a.done()?'Ödülü al':'Kilitli'}" ${!a.done()||state.claims.includes(a.id)?'disabled':''}>${state.claims.includes(a.id)?'✓':a.done()?'AL':'🔒'}</button>`).join('')}</div>`;}
function dailyPanelHTML(){const step=state.dailyStep%7;const spots=[[4.5,45.4,21,7],[29.5,45.4,20,7],[52.4,45.4,20,7],[76,45.4,20,7],[5,77.5,20,7],[30,77.5,20,7],[58,77,36,7]];return `<div class="exact-panel exact-daily"><img src="assets/daily-panel-exact.png" alt="Yedi günlük ödül takvimi"><button class="exact-close" id="exact-close" aria-label="Kapat"></button>${spots.map(([left,top,width,height],i)=>{const taken=i<step,ready=i===step&&!dayClaimed();return `<button ${i===step?'id="claim-daily"':''} class="daily-control ${ready?'ready':taken?'taken':'locked'}" style="left:${left}%;top:${top}%;width:${width}%;height:${height}%" ${ready?'':'disabled'} aria-label="${i+1}. gün: ${taken?'Alındı':ready?'Ödülü al':'Kilitli'}">${taken?'✓':ready?'AL':i===step?'YARIN':'🔒'}</button>`}).join('')}</div>`;}
